"use strict";

function wbButton(text,action,extra=""){return '<button type="button" class="button secondary small" data-wb="'+action+'" '+extra+'>'+h(text)+'</button>';}
function wbTable(headers,rows){return '<div class="table-wrap"><table><thead><tr>'+headers.map(t=>'<th>'+h(t)+'</th>').join('')+'</tr></thead><tbody>'+rows.join('')+'</tbody></table></div>';}
async function wbRefresh(view){await selectMerchant(state.merchant.merchant_id,state.report?.run_id);setView(view);}
function wbSelect(label,name,options,value){return '<label class="form-label">'+h(label)+'<select class="field" name="'+name+'">'+options.map(([v,t])=>'<option value="'+h(v)+'" '+(v===value?'selected':'')+'>'+h(t)+'</option>').join('')+'</select></label>';}

function renderWorkbench(){
  const w=state.extras?.workbench;if(!w||!state.merchant)return;
  renderConnections(w);
  if(typeof renderCompletion==="function")renderCompletion(w);
  appendSection('ledger',section('经营模式与单位经济', '<div class="panel"><p>'+h(w.models.notice)+'</p>'+w.models.models.map(r=>'<article class="knowledge-card"><strong>'+h(r.model.name)+'</strong> '+badge(r.model.status==='current'?'当前模式':'候选模式')+'<p>客户：'+h(r.model.customer_segment)+'；价值：'+h(r.model.value_proposition)+'<br>渠道：'+h(r.model.channel)+'；履约：'+h(r.model.fulfilment)+'</p><p>单位贡献 ¥'+yuan(r.unit_contribution)+'；'+r.model.period_days+'天保本订单 '+(r.break_even_orders??'待核实或单位贡献不足')+'；假设期间贡献 '+(r.assumed_period_contribution===null?'待填订单':'¥'+yuan(r.assumed_period_contribution))+'</p>'+r.issues.map(t=>'<p class="note-box amber">'+h(t)+'</p>').join('')+'<p class="muted">需求证据：'+h(r.model.demand_evidence)+'；来源：'+h(r.model.source_note)+'</p>'+wbButton('编辑经营模式','model','data-id="'+h(r.model.id)+'"')+'</article>').join('')+(w.models.models.length?'':'<p>先描述店铺服务谁、提供什么价值、怎样获客与交付，再测算成本和能力。</p>')+'</div>',wbButton('添加经营模式','model')));
  const a=w.accounts;
  appendSection('ledger',section('采购、收支与现金核对','<div class="panel"><p>'+h(a.notice)+'</p><p>流水收入 ¥'+yuan(a.incoming)+'；支出 ¥'+yuan(a.outgoing)+'；推算期末 '+(a.closing===null?'缺期初余额':'¥'+yuan(a.closing))+'；与底账差额 '+(a.balance_difference===null?'未知':'¥'+yuan(a.balance_difference))+'</p>'+a.warnings.map(t=>'<p class="note-box amber">'+h(t)+'</p>').join('')+wbTable(['采购单/日期','商品/数量','总额/已付/未付','应付款核对'],a.purchases.map(p=>'<tr><td>'+h(p.external_ref)+'<br>'+h(p.date)+'</td><td>'+h(p.sku)+' / '+p.quantity+'</td><td>¥'+yuan(p.total)+' / '+yuan(p.paid)+' / '+yuan(p.unpaid)+'</td><td>'+h(p.obligation_matched?'已匹配或已付清':'需人工录入/核对应付款')+wbButton('核对或更正采购','purchase','data-id="'+h(p.id)+'"')+'</td></tr>'))+'<details><summary>查看'+a.cash_entries.length+'笔收支记录</summary>'+wbTable(['日期/原单号','方向/类别','金额','来源'],a.cash_entries.map(c=>'<tr><td>'+h(c.date)+'<br>'+h(c.external_ref)+'</td><td>'+h(c.direction==='in'?'收入':'支出')+' / '+h(c.category)+'</td><td>¥'+yuan(c.amount)+'</td><td>'+h(c.source_note)+wbButton('核对或更正收支','cash','data-id="'+h(c.id)+'"')+'</td></tr>'))+'</details></div>',wbButton('期初现金','opening')+wbButton('录入采购单','purchase')+wbButton('录入收支','cash')+wbButton('CSV批量录入','csv')));
  if(w.research.some(r=>r.measurement)){
    const empty=$('#view-feedback .empty-state');if(empty){$('h3',empty).textContent='尚未记录逐商品收支反馈';$('p',empty).textContent='下方已有同口径经营观察。这里另行记录具体方案的商品销售、退款和费用；两类记录不自动相加，也不自动改账。';}
  }
  const r=state.report,usable=r?.result?.proposals?.length&&!r.ledger_changed&&!r.context_changed&&!['failed','cancelled','running'].includes(r.result.status);
  const latest=w.portfolios.at(-1),result=latest?.data.result;
  appendSection('analysis',section('经营组合与预算筛选','<div class="panel"><p>枚举最多10个已复核候选的组合，重新核算累计库存、费用、工时和逐日现金；支持互斥组、依赖和“暂不投入”。需要人工确认销量不重复，不预测流量或需求。</p>'+wbButton('选择候选并筛选组合','portfolio',usable?'':'disabled')+(result?'<article class="knowledge-card"><strong>最近一次筛选</strong><p>'+h(result.notice)+'</p><p>检查 '+result.checked+' 个组合；可行 '+result.feasible_count+' 个（包括条件满足时的暂不投入）。</p>'+wbTable(['入选代号','申报贡献','申报支出','零销量最低现金'],result.alternatives.map(x=>'<tr><td>'+h(x.keys.join('、')||'暂不新增投入')+'</td><td>¥'+yuan(x.evaluation.gross_profit_after_declared_trial_costs)+'</td><td>¥'+yuan(x.evaluation.trial_cash_commitment)+'</td><td>¥'+yuan(x.evaluation.scenarios[0].minimum_cash_before_receipts)+'</td></tr>'))+(result.best?.keys.length?wbButton('将首选组合送交交叉复核','adopt',usable?'':'disabled'):'<p>没有优于暂不投入的组合，或条件不足；先核账，不强行投入。</p>')+'<details><summary>查看被排除组合的原因</summary>'+result.rejected.map(x=>'<p>'+h(x.keys.join('、'))+'：'+h(x.reason)+'</p>').join('')+'</details></article>':'')+'</div>'));
  appendSection('feedback',section('预先设计、同口径测量与评价','<div class="panel"><p>先登记基准、观察期、指标、目标、最低样本、混杂因素和退出条件，再开展试验。目标冻结后不能因结果不好而改写。这里只做描述性评价，不证明因果。</p>'+state.extras.experiments.experiments.filter(t=>t.status==='planned'&&!w.research.some(r=>r.design.trial_id===t.id)).map(t=>'<div class="knowledge-card"><strong>'+h(t.hypothesis)+'</strong>'+wbButton('预先设计评价','design','data-id="'+h(t.id)+'"')+'</div>').join('')+w.research.map(r=>'<article class="knowledge-card"><strong>'+h(r.design.hypothesis)+'</strong> '+badge(r.evaluation.label)+'<p>观察 '+h(r.design.observe_start)+' 至 '+h(r.design.observe_end)+'；指标 '+h({revenue_per_day:'日均销售额',contribution_per_day:'日均贡献',conversion:'到店成交比例'}[r.design.metric])+'；目标 '+h(r.design.target_value)+'；至少 '+r.design.min_days+' 天 / '+r.design.min_visits+' 计数。</p><p>基准 '+h(r.evaluation.baseline??'待测量')+' → 实际 '+h(r.evaluation.actual??'待测量')+'；下一步：'+h(r.evaluation.next_action)+'</p><p class="muted">混杂因素：'+h(r.design.confounders)+'</p>'+wbButton('记录观察或留痕更正','measurement','data-id="'+h(r.id)+'"')+'</article>').join('')+'</div>'));
}

function openModel(id){
  const prior=state.merchant.business_models||[],m=prior.find(m=>m.id===id)||{id:'model_'+crypto.randomUUID().slice(0,8),status:'candidate',period_days:30};
  const texts={name:'模式名称',customer_segment:'服务哪类客户',customer_problem:'客户面临什么问题',value_proposition:'提供的核心价值',channel:'获客与销售渠道',fulfilment:'交付及售后方式',revenue_method:'怎样收费或获得收入',key_resources:'需要的资源',required_skills:'所需能力（每行一项）',available_skills:'已有能力（每行一项）',demand_evidence:'需求证据与待核实点',source_note:'资料来源与本次变更说明'};
  openFeature('描述经营模式并测算单位经济','<div class="form-grid two">'+Object.entries(texts).map(([k,label])=>featureText(label,k,m[k],'required maxlength="2000"')).join('')+wbSelect('模式状态','status',[['current','当前模式'],['candidate','候选模式']],m.status)+featureInput('测算期间天数','period_days',m.period_days,'type="number" min="1" max="366" required')+Object.entries({unit_revenue:'每订单收入（元）',unit_cost:'每订单全部变动成本（元，未知留空）',fixed_cost:'本期间固定成本（元）',investment:'初始投入（元）',assumed_orders:'本期间订单假设（未知留空）',weekly_hours:'每周所需工时'}).map(([k,t])=>featureInput(t,k,m[k],'type="number" min="0" step="'+(['assumed_orders','weekly_hours'].includes(k)?'1':'0.01')+'" '+(['assumed_orders','unit_revenue','unit_cost','fixed_cost','investment'].includes(k)?'':'required'))).join('')+'</div>'+unitCostFields(m)+'<label class="checkbox-line"><input name="costs_confirmed" type="checkbox" '+(m.costs_confirmed?'checked':'')+'>已核实这里列出的成本；未列成本仍需补充</label><p>订单是明示假设，保本点和回收期不证明可持续，现金仍需逐日核查。</p>',async form=>{const f=new FormData(form),d={...m,...Object.fromEntries(f),costs_confirmed:f.has('costs_confirmed')};for(const k of ['unit_revenue','unit_cost','fixed_cost','investment'])d[k]=moneyText(f.get(k),true);for(const k of ['period_days','weekly_hours'])d[k]=intText(f.get(k));d.assumed_orders=String(f.get('assumed_orders')).trim()?intText(f.get('assumed_orders')):null;readUnitCosts(f,d);await api(merchantRoot()+'/models',{models:[...prior.filter(p=>p.id!==m.id),d],source_note:d.source_note});await wbRefresh('ledger');});
}

function openOpening(){
  const a=state.merchant.accounts||{purchases:[],cash_entries:[]},o=a.opening||{};
  openFeature('期初现金与账簿范围',featureInput('期初日期（当天流水计入本期）','date',o.date||state.merchant.as_of,'type="date" required')+featureInput('期初现金（元）','balance',o.balance,'type="number" min="0" step="0.01" required')+featureText('来源与说明','source_note',o.source_note,'required')+'<p>修改期初不会改动底账余额；早于期初的流水会被拒绝。先对账再人工更新。</p>',async form=>{const f=new FormData(form),opening={date:f.get('date'),balance:moneyText(f.get('balance')),source_note:f.get('source_note')};await api(merchantRoot()+'/accounts',{accounts:{...a,opening},source_note:opening.source_note});await wbRefresh('ledger');});
}

function openAccount(kind,id){
  const a=state.merchant.accounts||{purchases:[],cash_entries:[]},purchase=kind==='purchase',prior=(a[purchase?'purchases':'cash_entries']||[]).find(x=>x.id===id);
  let fields=featureInput('发生日期','date',state.merchant.as_of,'type="date" required')+featureInput('原始单据或交易号（不可重复）','external_ref','','required maxlength="160"');
  if(purchase)fields+=wbSelect('采购商品','sku',state.merchant.products.map(p=>[p.sku,p.name]),'')+featureInput('采购件数','quantity','','type="number" min="1" step="1" required')+featureInput('采购单价（元）','unit_cost','','type="number" min="0" step="0.01" required')+featureInput('本单其他成本（元）','other_cost','','type="number" min="0" step="0.01" required')+featureInput('付款到期日','due_date',state.merchant.as_of,'type="date" required')+featureInput('供应方或匿名代号','supplier','','required')+wbSelect('对应底账应付款（可后续核对）','obligation_id',[['','尚未匹配'],...state.merchant.obligations.map(o=>[o.id,o.label_text||o.id])],'');
  else fields+=wbSelect('收支方向','direction',[['in','收入'],['out','支出']],'in')+wbSelect('类别','category',[['sale','销售收款'],['refund','销售退款'],['purchase','采购付款'],['rent','租金'],['other','其他'],['owner','业主投入或提取'],['loan','借入或归还']],'sale')+featureInput('实际金额（元）','amount','','type="number" min="0.01" step="0.01" required')+wbSelect('关联采购单（选中即作为采购付款）','purchase_id',[['','无关联'],...a.purchases.map(p=>[p.id,p.external_ref])],'');
  fields+=featureText('来源与核对说明','source_note','','required');
  openFeature(purchase?'录入采购单（不自动增加库存）':'录入实际收支（不重复记入现金底账）','<div class="form-grid two">'+fields+'</div><p>账簿用于核对。采购不自动入库，未付采购款需在底账应付款中确认。</p>',async form=>{const f=new FormData(form),r={...Object.fromEntries(f),id:prior?.id||(purchase?'po_':'cash_')+crypto.randomUUID().slice(0,8)};if(purchase){r.quantity=intText(f.get('quantity'));r.unit_cost=moneyText(f.get('unit_cost'));r.other_cost=moneyText(f.get('other_cost'));}else{r.amount=moneyText(f.get('amount'));if(r.purchase_id){r.category='purchase';r.direction='out';}}await api(merchantRoot()+'/accounts',{accounts:{...a,[purchase?'purchases':'cash_entries']:[...(a[purchase?'purchases':'cash_entries']||[]).filter(x=>x.id!==r.id),r]},source_note:r.source_note});await wbRefresh('ledger');});
  if(prior)for(const [key,value] of Object.entries(prior)){const field=$('[name="'+key+'"]',$('#feature-form'));if(field)field.value=value;}
}

const csvHeaders={cash_entries:'记录编号,日期,收支方向,款项类型,金额,原始单据号,关联采购编号,来源说明',purchases:'采购编号,日期,商品编号,数量,采购单价,其他成本,付款到期日,供应方,原始单据号,关联待付款编号,来源说明'};
function openCSV(){
  openFeature('上传收支或采购表格','<label class="form-label">选择CSV表格<input class="field" id="accounts-csv-file" type="file" accept=".csv,text/csv"></label>'+wbSelect('记录类型','kind',[['cash_entries','收支流水'],['purchases','采购单']],'cash_entries')+wbButton('下载中文表格模板','download-accounts-template')+'<p>Excel请另存为CSV UTF-8。收支方向填收入或支出；款项类型填销售、退款、采购、房租、其他、店主往来或借还款。</p><details><summary>查看两种CSV列名</summary><p>收支：</p><pre class="json-block">'+h(csvHeaders.cash_entries)+'</pre><p>采购：</p><pre class="json-block">'+h(csvHeaders.purchases)+'</pre></details>'+featureText('粘贴CSV内容（含列名）','csv','','required maxlength="500000"')+featureText('本批来源说明','source_note','','required')+wbButton('校验并预览','preview-csv')+'<div id="wb-csv-preview"></div><label class="checkbox-line"><input name="confirmed" type="checkbox" required>已预览本批原始单号、金额、方向及采购关联，确认保存；重复记录整批拒绝</label>',async form=>{const f=new FormData(form),data={...Object.fromEntries(f),confirmed:f.has('confirmed')};if(form.dataset.preview!==JSON.stringify([data.kind,data.csv]))throw new Error('CSV内容有变化，请重新预览');await api(merchantRoot()+'/accounts-import',data);await wbRefresh('ledger');},'保存已预览整批');
}

let wbCandidates=[];
async function openPortfolio(){
  const reports=await Promise.all(state.runs.slice(0,8).map(r=>api(merchantRoot()+'/runs/'+encodeURIComponent(r.id))));
  wbCandidates=[];
  for(const r of reports)if(!r.ledger_changed&&!r.context_changed&&r.result?.proposals&&!['failed','cancelled','running'].includes(r.result.status))for(const e of r.result.proposals){if(wbCandidates.length<10)wbCandidates.push({run_id:r.run_id,proposal_id:e.proposal.id,version:e.proposal.version,title:e.proposal.title,key:'c'+(wbCandidates.length+1)});}
  if(!wbCandidates.length)throw new Error('没有当前资料下可用的候选，请先重新核查');
  openFeature('组合筛选：先明确互斥与依赖','<p>相同互斥组只能选一项。清空组名才允许组合；依赖使用显示的代号，例如c1。组合会将投入、工时及同SKU数量相加，不能用同一批顾客重复假设成交。</p>'+wbCandidates.map((r,i)=>'<div class="knowledge-card wb-candidate" data-index="'+i+'"><label class="checkbox-line"><input type="checkbox" name="chosen" checked><strong>'+h(r.key+'：'+r.title+' v'+r.version)+'</strong></label><div class="form-grid two">'+featureInput('互斥组 '+r.key,'exclusive_group','alternatives','maxlength="100"')+featureInput('前置代号 '+r.key,'requires','','placeholder="可留空或填c1,c2"')+'</div></div>').join('')+featureInput('本次组合预算（元）','budget',state.merchant.max_trial_budget,'type="number" min="0" step="0.01" required')+wbSelect('排序目标','objective',[['contribution','申报贡献较高'],['cash_floor','零销量现金底线较高']],'contribution')+'<label class="checkbox-line"><input type="checkbox" name="independent">我已核对不同动作的需求与工作量，确认组合销量不重复；仍只是待验证假设</label>',async form=>{const f=new FormData(form),candidates=$$('.wb-candidate',form).filter(r=>$('[name=chosen]',r).checked).map(r=>({...wbCandidates[Number(r.dataset.index)],exclusive_group:$('[name=exclusive_group]',r).value,requires:$('[name=requires]',r).value.split(',').map(s=>s.trim()).filter(Boolean)}));await api(merchantRoot()+'/portfolio',{candidates,independent:f.has('independent'),budget:moneyText(f.get('budget')),objective:f.get('objective')});await wbRefresh('analysis');},'枚举组合并保留筛选记录');
}

function researchFields(value,baseline=false){
  const prefix=baseline?'base_':'',d=value||{};
  return '<div class="form-grid two">'+(baseline?featureInput('基准开始日',prefix+'start',d.start,'type="date" required')+featureInput('基准截止日',prefix+'end',d.end,'type="date" required'):featureInput('观察截止日','end',d.end,'type="date" required'))+Object.entries({revenue:'销售额',goods_cost:'售出商品成本',expenses:'经营费用',visits:'到店计数',buyers:'成交计数'}).map(([k,t])=>featureInput((baseline?'基准':'观察')+t,prefix+k,d[k],'type="number" min="0" step="'+(['visits','buyers'].includes(k)?'1':'0.01')+'" required')).join('')+featureText(baseline?'基准记录来源':'观察记录来源',prefix+'source_note',d.source_note,'required')+'</div>';
}

async function openDesign(id,draftId){
  const preview=draftId?await api(merchantRoot()+'/draft-preview',{trial_id:id,draft_id:draftId}):null;
  const d=preview?preview.design:await api(merchantRoot()+'/design-template',{trial_id:id});
  openFeature('在开展前冻结试验评价设计','<p>保存后本次设计不能修改。请先核对基准期及阈值，再将试验状态改为开展中。观察金额按同一经营范围填写，不能拿全店营业额与单项试验收款混比。</p>'+(preview?'<div class="note-box">'+h(preview.notice)+'<p>来源：'+h(executionName(preview.source_mode))+'；目标依据：'+h(preview.draft_original.target_basis)+'</p></div>':'')+designScopeFields(d)+featureText('待验证假设','hypothesis',d.hypothesis,'required')+featureText('本次具体改变什么','intervention',d.intervention,'required')+wbSelect('主要评价指标','metric',[['revenue_per_day','日均销售额（元/天）'],['contribution_per_day','日均贡献（元/天）'],['conversion','成交比例（0到1）']],d.metric)+'<div class="form-grid two">'+featureInput('预设目标值（仅日均贡献允许负数）','target_value',d.target_value,'type="number" step="0.01" required')+featureInput('最少观察天数','min_days',d.min_days,'type="number" min="1" max="30" required')+featureInput('最少到店计数','min_visits',d.min_visits,'type="number" min="0" required')+featureInput('观察开始日','observe_start',d.observe_start,'type="date" required')+featureInput('观察结束日','observe_end',d.observe_end,'type="date" required')+'</div>'+researchFields(d.baseline,true)+['comparison_method','confounders','stop_rule','source_note'].map((k,i)=>featureText(['对照及统计口径','可能影响结果的其他因素','人工停止规则（预算和现金线另由程序检查）','设计来源与核对说明'][i],k,d[k],'required')).join('')+exitFields(d),async form=>{const f=new FormData(form),data={...d,...Object.fromEntries(f),scope_confirmed:f.has('scope_confirmed'),exit_rules:readExits(form),target_value:String(f.get('target_value')).trim(),min_days:intText(f.get('min_days')),min_visits:intText(f.get('min_visits')),baseline:{}};for(const k of ['start','end','source_note','scope_id','count_basis'])data.baseline[k]=f.get('base_'+k);for(const k of ['revenue','goods_cost','expenses'])data.baseline[k]=moneyText(f.get('base_'+k));for(const k of ['visits','buyers'])data.baseline[k]=intText(f.get('base_'+k));await api(merchantRoot()+'/design',data);await wbRefresh('feedback');},'冻结本次评价设计');
}

function openMeasurement(id){
  const r=state.extras.workbench.research.find(r=>r.id===id),m=r.measurement||{};
  openFeature('记录同口径观察与更正','<p>固定指标及目标不变；每次记录自 '+h(r.design.observe_start)+' 起累计值。更正须说明原因，原观察不会删除。</p>'+measurementScopeFields(r,m)+researchFields(m)+featureInput('本试验累计实际投入（元）','trial_spend',m.trial_spend,'type="number" min="0" step="0.01" required')+featureInput('实际可用现金余额（元）','closing_cash',m.closing_cash,'type="number" min="0" step="0.01" required')+featureText('本次观察或更正原因','change_reason','','required'),async form=>{const f=new FormData(form),data={...Object.fromEntries(f),design_id:id,supersedes_id:r.measurement_id};for(const k of ['revenue','goods_cost','expenses','trial_spend','closing_cash'])data[k]=moneyText(f.get(k));for(const k of ['visits','buyers'])data[k]=intText(f.get(k));await api(merchantRoot()+'/measurement',data);await wbRefresh('feedback');},'保存观察并评价');
}

document.addEventListener('click',async event=>{
  const b=event.target.closest('[data-wb]');if(!b||b.disabled)return;
  if(state.busy){toast('请先等待当前任务完成');return;}
  b.disabled=true;
  try{
    const action=b.dataset.wb;
    if(action==='example'){const l=await api('/api/planning-example');l.merchant_id='plan_'+crypto.randomUUID().slice(0,8);await api('/api/ledgers',l);await reloadMerchants(l.merchant_id);setView('ledger');}
    else if(action==='model')openModel(b.dataset.id);
    else if(action==='opening')openOpening();
    else if(action==='cash'||action==='purchase')openAccount(action,b.dataset.id);
    else if(action==='csv')openCSV();
    else if(action==='download-accounts-template'){const kind=$('#feature-form [name=kind]').value,url=URL.createObjectURL(new Blob(['\ufeff'+csvHeaders[kind]+'\n'],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(kind==='cash_entries'?'收支表格模板':'采购表格模板')+'.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
    else if(action==='portfolio')await openPortfolio();
    else if(action==='design')await openDesign(b.dataset.id);
    else if(action==='measurement')openMeasurement(b.dataset.id);
    else if(action==='preview-csv'){const form=$('#feature-form'),f=new FormData(form),data={kind:f.get('kind'),csv:f.get('csv')};const result=await api(merchantRoot()+'/accounts-preview',data);form.dataset.preview=JSON.stringify([data.kind,data.csv]);$('#wb-csv-preview').innerHTML='<p>校验通过：'+result.rows.length+'行；尚未保存。</p>'+wbTable(Object.keys(result.rows[0]),result.rows.slice(0,10).map(r=>'<tr>'+Object.values(r).map(v=>'<td>'+h(v)+'</td>').join('')+'</tr>'))+'<p>最多展示前10行，请核对完整CSV后确认。</p>';}
    else if(action==='adopt'){const record=state.extras.workbench.portfolios.at(-1),best=record?.data.result.best;if(!best?.keys.length)throw new Error('没有需提交的组合');if(JSON.stringify(record.data.ledger_snapshot)!==JSON.stringify(state.merchant))throw new Error('底账已变化，请重新筛选');const draft={...best.proposal,id:'combo_'+crypto.randomUUID().slice(0,8),version:1,new_candidate:true,rationale:best.proposal.rationale+'；筛选记录 '+record.id};await startTask({mode:'manual',draft,parent_run:state.report.run_id});}
  }catch(err){toast(err.message);}finally{b.disabled=false;}
});


document.addEventListener('change',async event=>{if(event.target.id!=='accounts-csv-file'||!event.target.files[0])return;try{const file=event.target.files[0];if(file.size>600000)throw new Error('表格过大，请分批上传');const form=document.querySelector('#feature-form');form.querySelector('[name=csv]').value=await file.text();delete form.dataset.preview;form.querySelector('[name=confirmed]').checked=false;document.querySelector('#wb-csv-preview').textContent='表格已读入，请点击校验并预览。';}catch(err){toast(err.message)}});
